#include <iostream>
#include <string>
int main() {
    bool condition1 = true;  // First operand
    int value = 0;          // Used in second operand with side effect
    if (condition1 && (value++ > 0)) {  // Logical AND with potential side effect
        std::cout << "Both true, value is now: " << value << std::endl;
    } else {
        std::cout << "Not both true, value unchanged: " << value << std::endl;
    }
    return 0;
}
